INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('641a4f93-bc93-4348-bc88-279c2b3b40d3', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "af49849c-8096-466a-bafc-8b0249893b56", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "96ed58b5-2afc-48f5-9438-dbda535eb88c", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "f1b4f12e-5912-4476-ba63-8ca4119a8d21", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0555097a-2080-480a-a733-2de7790cb9f8", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "49f30675-4d55-4b78-9a26-ec1b6aaf0206", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "32a21cd1-9700-4e96-b8ef-2817dd228718", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "31e6fb75-4be2-458f-8f3f-5da5f933e74b", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "4832cdbb-fc8a-4a07-af43-407077249a67", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "8878e6fc-3ca6-4ac6-9b4e-3068ccaff660", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "630ed0ab-4578-4690-8420-3d7b0ef5478b", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "59433ecd-1b04-4d10-a126-059994fc5655", "text": "Igaz", "isCorrect": true}, {"id": "16940aca-1252-466e-b353-ff085deedff9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b824045a-cbd4-4516-b419-08365566dc35", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "9ee260f5-9b6c-404a-a151-65c1183fab6b", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "62504774-fbd4-4b96-aebd-85b7d6d7608c", "text": "815", "isCorrect": false}, {"id": "1f67d4d6-ff26-4602-85f5-829fb353becd", "text": "812", "isCorrect": false}, {"id": "735bd70d-51ec-4d96-835f-e0911fdfe50b", "text": "811", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d9710fcf-7322-4453-b1fa-f2e0ce4da21d', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "b3e45b81-815d-4d30-b204-c7d9b41ddb1a", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "d86e76cb-9057-4800-a676-5a8af3127b65", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "1a0acb3a-4f25-447e-9f28-82f0403248e5", "text": "4/6", "isCorrect": false}, {"id": "61a1ece2-1c54-4fa4-89a5-b7ed17b68570", "text": "4/4", "isCorrect": false}, {"id": "4400cd59-3221-4833-963e-f8ca98303aa5", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "8a4f7790-536f-47b2-b9e1-a3dda41e6cbf", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "d3d091cd-7b0b-4dda-9ba6-ff882b058395", "text": "2/5", "isCorrect": true}, {"id": "e145cb7d-df07-4188-9926-82bec309fa12", "text": "6/15", "isCorrect": false}, {"id": "3eddc0ac-9ec5-4bbb-b368-425ca40316d0", "text": "5/8", "isCorrect": false}, {"id": "05eba211-8922-4ef8-bd62-e6e4857b7e86", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "b8ba0d9f-c13c-4877-b455-4924ef9f5436", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "0fb84771-1fb7-4d3e-b1df-7bd13f8c4f6a", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "bc5ffe7c-10aa-4f86-829c-98d504098cf5", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "40d6b5e6-1938-429e-8338-9c21821832c3", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "56db7a58-f30c-468f-81f4-83e060a1a5ec", "text": "Igaz", "isCorrect": true}, {"id": "2dee7a80-d172-4ebf-b8b1-182c69ac2c29", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f8b94e01-f5a9-4cd7-bd81-ffc410b6c6e9", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a11fbe41-2dab-4a81-97ad-593fafa8723a', '21feff02-016d-46e2-bb9d-c27495133b1b', '133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok', 'Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "bd7b0601-9308-43be-ab2f-f4b7f5bebf99", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "1d5f4ab5-c372-465c-94e4-bc0ce5260198", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "b1ee73a2-d489-4893-aaf6-4270aa65748f", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "d56c6b52-47ce-4340-9677-7f708a4b94b3", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "48385248-4272-4745-9e03-9012c652ae33", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "b41b90f4-33ab-4ca6-811b-31f053c7f974", "text": "Igaz", "isCorrect": true}, {"id": "d430c7b7-7415-42fe-a802-c07935283bb5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "780f8b4f-d42e-4f83-a071-182c35d0c55d", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "245cb4b0-9f87-4dff-a768-2d78a042f783", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "281d674b-e1d3-4435-b4f8-5a6cfb149645", "text": "Derékszög", "isCorrect": true}, {"id": "8d97fb31-f198-4e53-95d0-b52cf15049c0", "text": "Hegyesszög", "isCorrect": false}, {"id": "7a39b73d-7a7f-4e45-85be-718aec370bd0", "text": "Tompaszög", "isCorrect": false}, {"id": "b0b5d4eb-98d5-44e1-ab24-e08e11d291dc", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c4713e2d-6b5e-4e6f-bc85-722250a2bb45', '21feff02-016d-46e2-bb9d-c27495133b1b', '134. óra: Arányosság, százalék, szöveges feladatok', 'Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "8998b979-cc10-4f2d-92e6-c2dbfba52cb7", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "cd5846ee-aabe-483f-b71a-98b4663dd2ba", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "d68ffd6c-1f87-4d0c-9103-382cb4ddec18", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "99423c68-14f5-4f12-85a5-a3e125807825", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "ca35182b-1c61-4d13-b43a-d48cbf774203", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "7f6e7e76-d4be-4e05-9c61-e633233bc10e", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "31e9621c-4492-45d9-a582-1090f12634af", "text": "Igaz", "isCorrect": true}, {"id": "a2b6ae7b-b263-4f40-89bd-a17992d9ba20", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b0fcf8bf-9b38-461d-b52d-561934261e68", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1e6fb4c2-ea26-41c1-9386-e4b90dbe1180', '21feff02-016d-46e2-bb9d-c27495133b1b', '135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok', 'Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "d29263c2-21ed-42dd-aa3c-1b8e47e64adb", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "807cb4c3-5aa0-4aac-b716-8d377628251e", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "76bd9d16-85ef-422f-9a44-e29fe3e1695c", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "eca2ddcd-836c-4c09-bc89-fb44990aa83a", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "023a9ae7-47f7-495d-adc3-2d480acac620", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "343a7b55-0634-4554-8543-0c7bad0c43cc", "text": "Igaz", "isCorrect": true}, {"id": "3f32b7f8-d61c-4550-b279-3855bca0cabc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "60999e88-41b2-4b52-8ec0-dec28bbea4c0", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "c8e0d6ef-ab1c-46de-9afa-b1bcbfae9fe9", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1079f9dd-799e-4cf0-9813-3f728e5c1166', '21feff02-016d-46e2-bb9d-c27495133b1b', '136. óra: Az éves munka értékelése', 'Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "a4588e9d-7507-46f2-abe5-3421485986ba", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "79fe7ab2-a716-4218-b5eb-7b83a08b46b5", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "a9e9f6ab-b835-4ea4-aa1b-0f08895bb0d1", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "3c81bfe7-c5e4-4b8f-8087-00e3b23ab368", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "b69c5cbb-29d4-48ae-b649-b5520c4a8a45", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "d80c0e83-d92f-4e05-b314-fbfe8aa1a0bf", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "a12f4631-58d8-4cf8-a815-09c3c5af40eb", "text": "Igaz", "isCorrect": true}, {"id": "3f22700a-1f40-4eab-b6de-19d50c16fbe8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f10ece1c-5246-450c-9cb7-03d0d7a04c9f", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "bcd68d7e-6949-4b73-928f-1987c72a6e7d", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "88f8c915-2259-4891-a7f9-4f54469f66ff", "text": "Igaz", "isCorrect": true}, {"id": "d56ac9c7-914b-44ac-9f44-d946acfb2a9b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2962fc67-e26e-4302-bbea-868d43603bfb", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "a45a4b72-27ba-447d-942b-294036c1bd83", "text": "Igaz", "isCorrect": true}, {"id": "4ef8ef61-a05c-4eaa-9e89-3c6eddaef057", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cecaad13-e83d-4ea5-b2bf-ceb5ce2060f2", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "a70ae4ae-1be0-4b65-b53b-8d6086527646", "text": "Igaz", "isCorrect": true}, {"id": "5cbd58bc-9c61-4bd8-ae17-cad05c447388", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "22728544-3206-4bdf-bd6a-353ce4c6c7a7", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "292a6828-eaea-494a-824d-87e17e991c89", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "446463c9-c97a-4fba-8bc0-1bc06bbad32a", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "a78a7c52-fc1d-4758-8653-de8e63ed7267", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "277f7128-29a4-4f16-bd79-63476b482853", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;